function sumOfMinimums(nums: number[]): number {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let low = Infinity;
    for (let j = i; j < nums.length; j++) {
      low = Math.min(low, nums[j]);
      total += low;
    }
  }
  return total % 1000000007;
}

