function sumOfMinimums(nums: number[]): number {
  const MOD = 1000000007, n = nums.length;
  const left = new Array(n).fill(-1), right = new Array(n).fill(n);
  const stack: number[] = []; // indexes, values increasing
  for (let i = 0; i < n; i++) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) right[stack.pop()!] = i;
    if (stack.length) left[i] = stack[stack.length - 1];
    stack.push(i);
  }
  let total = 0;
  for (let i = 0; i < n; i++) total = (total + nums[i] * (i - left[i]) * (right[i] - i)) % MOD;
  return total;
}

