        left, right = [-1] * n, [n] * n
        stack = []  # indexes, values increasing
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] >= x:
                right[stack.pop()] = i
            if stack:
                left[i] = stack[-1]
            stack.append(i)
        return sum(nums[i] * (i - left[i]) * (right[i] - i) for i in range(n)) % MOD

